import { dirname, isAbsolute, posix, relative, resolve, sep } from 'node:path'

export const VOID_GENERATED_DIRECTORY = '.cloudconfig/void'
export const GENERATED_VOID_HEADER =
  '// Generated by CloudConfig for Void. Edit cloud.config.ts instead.'

export function relativeImportPath(from: string, target: string): string {
  const path = relative(dirname(from), target).split(sep).join('/')
  return path.startsWith('./') || path.startsWith('../') ? path : `./${path}`
}

/** Normalize a Void application directory without allowing it to escape the project. */
export function normalizeVoidSourceDirectory(value: string | undefined): string {
  if (value === undefined) return ''
  const normalized = posix.normalize(value.replaceAll('\\', '/')).replace(/\/+$/, '')
  if (
    !value ||
    value.trim() !== value ||
    isAbsolute(value) ||
    /^[A-Za-z]:/.test(value) ||
    value.split(/[\\/]/).includes('..') ||
    normalized === '.' ||
    normalized.startsWith('/')
  ) {
    throw new Error('Void sourceDir must be a non-empty relative application directory.')
  }
  if (
    normalized === VOID_GENERATED_DIRECTORY ||
    normalized.startsWith(`${VOID_GENERATED_DIRECTORY}/`)
  ) {
    throw new Error(
      'Keep Void application sources outside the generated .cloudconfig/void directory.',
    )
  }
  return normalized
}

export function voidProjectPaths(projectDir: string, sourceDir?: string) {
  const sourceRoot = resolve(projectDir, normalizeVoidSourceDirectory(sourceDir))
  const generatedRoot = resolve(projectDir, VOID_GENERATED_DIRECTORY)
  return {
    sourceRoot,
    generatedRoot,
    schemaPath: resolve(sourceRoot, 'db/schema.ts'),
    migrationsPath: resolve(sourceRoot, 'db/migrations'),
    environmentFilePath: resolve(sourceRoot, 'env.ts'),
    generatedSchemaPath: resolve(generatedRoot, 'db/schema.ts'),
    envPath: resolve(generatedRoot, 'env.ts'),
    generatedWorkerPath: resolve(generatedRoot, 'worker.ts'),
  }
}
